# Cleanup for the stale epass.* build residue under libs/, 2026-09-01.
#
# libs/nativeweb.security and libs/nativeweb.mail still hold obj/ trees from before
# the 2026-07-26 rename (bc7e205, epass.* -> nativeweb.*). Their generated
# AssemblyInfo files still declare AssemblyTitle "epass.security" and "epass.mail",
# which is how they turn up in a grep for epass vocabulary in a repository that is
# supposed to hold none.
#
# They are build output: untracked, gitignored, and regenerated by the next build
# under the current name. Nothing reads them -- the projects build against the obj
# trees MSBuild writes for the current project name, not these. Removing them costs
# one rebuild of two libraries.
#
# Every claim above is re-made here as a command: tracked-ness, and that the file
# really does name an epass assembly. A file that has stopped matching is refused,
# not removed.
#
# Bare invocation is the dry run. -Execute is the only way to act. Nothing here is
# irreversible in the way a source file is -- a build reproduces all of it -- so
# -Execute alone is enough.
#
# Nothing here is run by an agent. The user runs it.

[CmdletBinding()]
param(
    [Alias('e')][switch]$Execute
)

$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
$repo = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$failed = $false

$roots = @(
    'libs/nativeweb.security/obj',
    'libs/nativeweb.mail/obj'
)

Write-Host "Stale epass.* AssemblyInfo residue:"

$targets = @()
foreach ($rel in $roots) {
    $full = Join-Path $repo $rel

    if (-not (Test-Path $full)) {
        Write-Host "  skip:  $rel does not exist"
        continue
    }

    $stale = @(Get-ChildItem -LiteralPath $full -Recurse -File -Filter 'epass.*' -ErrorAction SilentlyContinue)
    if ($stale.Count -eq 0) {
        Write-Host "  skip:  $rel holds no epass.* file"
        continue
    }

    foreach ($file in $stale) {
        $relFile = $file.FullName.Substring($repo.Length + 1).Replace('\', '/')

        git -C $repo ls-files --error-unmatch -- $relFile > $null 2>&1
        if ($LASTEXITCODE -eq 0) {
            Write-Host "  refuse: $relFile is tracked by git. Build output is not, so this is"
            Write-Host "          something else. Left alone."
            $failed = $true
            continue
        }

        # What makes a file here residue is where it sits, not what is inside it: an
        # obj/ tree belonging to a project named nativeweb.*, holding output named for
        # an assembly that project has not produced since 2026-07-26. Most of these are
        # binary caches with no readable name in them, so a content check would refuse
        # the very files it is meant to identify. The path is asked instead.
        if ($relFile -notmatch '^libs/nativeweb\.[a-z.]+/obj/') {
            Write-Host "  refuse: $relFile is not under a nativeweb.* project's obj/ tree."
            Write-Host "          Left alone."
            $failed = $true
            continue
        }

        Write-Host "  would remove: $relFile"
        $targets += $file.FullName
    }
}

Write-Host ""
Write-Host "NOT removed by this script, and not candidates:"
Write-Host "  the rest of obj/ and bin/ -- current build output, and a rebuild's business"
Write-Host "  anything under libs/*/  that is not obj/ -- that is source"
Write-Host "  any branch -- branches are never deleted here"

if ($targets.Count -eq 0) {
    Write-Host ""
    Write-Host "Nothing to do."
    if ($failed) { exit 1 }
    exit 0
}

if (-not $Execute) {
    Write-Host ""
    Write-Host "Dry run. Nothing was changed."
    Write-Host "Re-run with -Execute to remove the $($targets.Count) file(s) above."
    exit 0
}

foreach ($full in $targets) {
    Remove-Item -LiteralPath $full -Force
    Write-Host "removed: $full"
}

Write-Host ""
Write-Host "Removed $($targets.Count) file(s). The next 'dotnet build' regenerates what it needs."

if ($failed) { exit 1 }
